import functools

def sensitive_variables(*variables):
    def decorator(func):
        @functools.wraps(func)
        def sensitive_variables_wrapper(*func_args, **func_kwargs):
            if variables:
                sensitive_variables_wrapper.sensitive_variables = variables
            else:
                sensitive_variables_wrapper.sensitive_variables = '__ALL__'
            return func(*func_args, **func_kwargs)

        # Try to preserve signature using __signature__
        sensitive_variables_wrapper.__signature__ = inspect.signature(func)

        return sensitive_variables_wrapper
    return decorator

def my_authenticate(request, username, password):
    return "success"

decorated_authenticate = sensitive_variables('username')(my_authenticate)

print(f"Function: {decorated_authenticate}")
print(f"Original function: {my_authenticate}")

try:
    # This should match
    print("Matching call:")
    print(inspect.getcallargs(decorated_authenticate, request=None, username='admin', password='password'))
    print("Matched successfully")
except TypeError as e:
    print(f"Failed to match: {e}")

try:
    # This should FAIL (TypeError) because 'extra_arg' is not in the signature
    print("\nNon-matching call:")
    print(inspect.getcallargs(decorated_authenticate, request=None, username='admin', password='password', extra_arg='extra'))
    print("Matched unexpectedly")
except TypeError as e:
    print(f"Correctly failed to match: {e}")
